const candidates = $input.first().json.body.candidates;

return candidates.map(candidate => ({
  json: candidate
}));

const requiredFields = [
  "candidateId",
  "fullName",
  "email",
  "phone",
  "jobId",
  "resumeUrl"
];

const candidate = $json;

const missingFields = requiredFields.filter(
  field => !candidate[field] || String(candidate[field]).trim() === ""
);

return {
  json: {
    ...candidate,
    validationStatus: missingFields.length === 0 ? "VALID" : "INVALID",
    missingFields
  }
};

const candidate = $('Code in JavaScript1').item.json;

const airtableRecord = $('Create or update a record').item.json;

const rawText = $json.text || "";

const resumeText = rawText
  .replace(/\r\n?/g, "\n")
  .replace(/[ \t]+/g, " ")
  .replace(/\n{3,}/g, "\n\n")
  .trim();

if (resumeText.length < 100) {
  throw new Error(
    `CV extraction failed for ${candidate.candidateId}`
  );
}

const normalizedForCheck = resumeText
  .replace(/\s+/g, " ")
  .toLowerCase();

const nameMatches = normalizedForCheck.includes(
  candidate.fullName.trim().toLowerCase()
);

return {
  json: {
    candidateId: candidate.candidateId,
    fullName: candidate.fullName,
    airtableRecordId: airtableRecord.id,
    resumeUrl: candidate.resumeUrl,
    resumeText,
    resumeCharacterCount: resumeText.length,
    nameMatchesCV: nameMatches,
    extractionStatus: nameMatches
      ? "SUCCESS"
      : "NAME_MISMATCH"
  }
};

const candidate = $('Normalize Candidate CV Text').item.json;

// Airtable may return flat fields or a nested fields object.
const jobResult = $json;
const job = jobResult.fields ?? jobResult;

// Convert Airtable values to consistent strings.
const asText = (value) => {
  if (Array.isArray(value)) return value.join(", ");
  return String(value ?? "").trim();
};

const jobId = asText(job["Job ID"]);
const jobDescription = asText(job["Job Description"]);
const requiredSkills = asText(job["Required Skills"]);
const minimumExperience = Number(job["Minimum Years Experience"]);

// Validate the context before calling Gemini.
if (candidate.extractionStatus !== "SUCCESS") {
  throw new Error(
    `CV validation failed: ${candidate.candidateId}`
  );
}

if (!jobId || !jobDescription || !requiredSkills) {
  throw new Error("Job requirements are incomplete");
}

if (!Number.isFinite(minimumExperience)) {
  throw new Error("Minimum experience must be a number");
}

// Return one complete AI evaluation payload.
return {
  json: {
    candidateId: candidate.candidateId,
    candidateRecordId: candidate.airtableRecordId,
    candidateName: candidate.fullName,
    resumeUrl: candidate.resumeUrl,
    resumeText: candidate.resumeText,

    jobRecordId: jobResult.id,
    jobId,
    jobTitle: asText(job["Job Title"]),
    jobDescription,
    requiredSkills,
    preferredSkills: asText(job["Preferred Skills"]),
    minimumExperience,
    educationRequirements: asText(job["Education Requirements"]),
    certificationRequirements: asText(job["Certification Requirements"]),
    employmentType: asText(job["Employment Type"]),
    jobLocation: asText(job["Location"]),

    evaluationStatus: "READY_FOR_GEMINI"
  }
};

/*
 GROUP 8: STRICT RULE-BASED CANDIDATE EVALUATOR

 Temporary replacement for Gemini.
 n8n Mode: Run Once for Each Item

 Scoring rubric:
 Required skills: 40
 Relevant experience: 25
 Projects: 20
 Engineering practices: 10
 Preferred skills: 5

 SIMULATION ONLY - HUMAN REVIEW REQUIRED.
*/

function evaluate(candidate) {
  const candidateId = String(candidate.candidateId || "").trim();
  const resume = String(candidate.resumeText || "").replace(/\r/g, "");
  const name = String(
    candidate.candidateName || candidate.fullName || ""
  ).trim();

  if (
    !candidateId ||
    !String(
      candidate.candidateRecordId ||
      candidate.airtableRecordId ||
      ""
    )
  ) {
    throw new Error("Candidate ID or Airtable Record ID missing");
  }

  if (resume.length < 150) {
    throw new Error(`CV missing or too short: ${candidateId}`);
  }

  if (
    name &&
    !resume.toLowerCase().includes(name.toLowerCase())
  ) {
    throw new Error(`Wrong CV paired with ${candidateId}`);
  }

  if (candidate.jobId !== "JOB-001") {
    throw new Error(
      `Evaluator configured for JOB-001, got ${candidate.jobId}`
    );
  }

  // 1. TEXT NORMALIZATION

  const normal = text =>
    String(text || "")
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, " ")
      .replace(/\s+/g, " ")
      .trim();

  const has = (text, aliases) =>
    aliases.some(x =>
      (` ${normal(text)} `).includes(` ${normal(x)} `)
    );

  // 2. SEPARATE CV SECTIONS

  const HEADERS = [
    "PROFESSIONAL SUMMARY",
    "CORE COMPETENCIES",
    "PROFESSIONAL EXPERIENCE",
    "PRACTICAL TRAINING",
    "SELECTED PROJECTS",
    "EDUCATION",
    "PROFESSIONAL CERTIFICATIONS",
    "ADDITIONAL INFORMATION"
  ];

  const split = {};
  let current = "PREAMBLE";
  split[current] = [];

  for (const line of resume.split("\n")) {
    const heading = line.trim().toUpperCase();

    if (HEADERS.includes(heading)) {
      current = heading;
      split[current] = [];
    } else {
      split[current].push(line);
    }
  }

  const section = h => (split[h] || []).join("\n").trim();

  const summary = section("PROFESSIONAL SUMMARY");
  const skills = section("CORE COMPETENCIES");
  const work = section("PROFESSIONAL EXPERIENCE");
  const training = section("PRACTICAL TRAINING");
  const projects = section("SELECTED PROJECTS");

  const jobs = work || training;
  const claims = [summary, skills].join(" ");

  // Detect demonstrated experience, not just listed skills.

  const bulletText = (jobs + "\n" + projects)
    .split(/\n\s*[•*]\s*/)
    .slice(1);

  const action =
    /\b(developed|built|implemented|maintained|optimized|designed|tested|refactored|created|deployed|configured|debugged|resolved|triaged|introduced|automated|wrote|prepared|contributed|connected|reviewed|investigated|added|managed|integrated|produced|documented|measured)\b/i;

  const evidence = bulletText.filter(t =>
    action.test(normal(t))
  );

  const applied = aliases =>
    evidence.some(t => has(t, aliases));

  const claimed = aliases =>
    has(claims, aliases);

  // 3. REQUIRED TECHNICAL SKILLS: 40

  const defs = [
    {
      name: "Python",
      points: 13,
      aliases: ["python", "python based", "python service"],
      basic: true
    },
    {
      name: "REST API Development",
      points: 10,
      aliases: [
        "rest api", "rest apis", "restful api",
        "api request", "service endpoints",
        "backend api", "fastapi", "django rest", "flask"
      ]
    },
    {
      name: "SQL / Relational Databases",
      points: 8,
      aliases: [
        "sql", "postgresql", "mysql", "sqlite",
        "database queries", "database access",
        "data access", "database query"
      ]
    },
    {
      name: "Git / Version Control",
      points: 3,
      aliases: [
        "git", "github actions",
        "pull requests", "version control"
      ]
    },
    {
      name: "Testing",
      points: 4,
      aliases: [
        "pytest", "unit testing", "regression checks",
        "test cases", "test matrix",
        "regression testing", "automated tests",
        "test evidence"
      ]
    },
    {
      name: "Debugging",
      points: 2,
      aliases: [
        "debugging", "troubleshoot", "defects",
        "error handling", "exception reporting",
        "resolved edge case",
        "reproduced reported defects",
        "production error", "triaged defects"
      ]
    }
  ];

  let required = 0;

  const matchedSkills = [];
  const missingSkills = [];
  const evidenceLevels = {};

  for (const d of defs) {
    const done = applied(d.aliases);
    const listed = claimed(d.aliases);

    const basicOnly =
      d.basic &&
      has(claims, ["basic python"]) &&
      !done;

    let got = done
      ? d.points
      : listed
        ? Math.floor(d.points * 0.45)
        : 0;

    if (basicOnly) {
      got = Math.min(got, 2);
    }

    required += got;

    evidenceLevels[d.name] = done
      ? "DEMONSTRATED"
      : listed
        ? "LISTED_ONLY"
        : "NOT_FOUND";

    if (got > 0) {
      matchedSkills.push(
        done
          ? d.name
          : `${d.name} (listed only)`
      );
    } else {
      missingSkills.push(
        `${d.name} (not verified in CV)`
      );
    }
  }

  const coreApplied = {
    python: applied(defs[0].aliases),
    api: applied(defs[1].aliases),
    database: applied(defs[2].aliases)
  };

  const coreCount = Object.values(coreApplied)
    .filter(Boolean).length;

  // 4. RELEVANT PROFESSIONAL EXPERIENCE: 25

  const roleLines = jobs
    .split("\n")
    .filter(line =>
      line.includes("|") &&
      /(developer|engineer|programmer|tester|technician|analyst|assistant|designer|coordinator|specialist|executive|intern)/i.test(line)
    )
    .map(x => x.split("|")[0].trim());

  const role = normal(roleLines.join(" "));

  let roleFactor = 0;

  if (
    /(software engineer intern|software development intern|junior software developer|junior developer)/.test(role)
  ) {
    roleFactor = 0.55;
  } else if (
    /(backend|back end|python developer|api engineer|senior backend)/.test(role)
  ) {
    roleFactor = 1;
  } else if (
    /(software developer|software engineer|full stack)/.test(role)
  ) {
    roleFactor = 0.9;
  } else if (
    /(web developer|application developer|mobile developer)/.test(role)
  ) {
    roleFactor = 0.65;
  } else if (
    /(data engineer|devops|automation engineer)/.test(role)
  ) {
    roleFactor = 0.4;
  }

  const expMatch =
    resume.match(
      /Relevant experience\s*:\s*(\d+(?:\.\d+)?)\s*years?/i
    ) ||
    resume.match(
      /\b(\d+(?:\.\d+)?)\s*years? of experience\b/i
    );

  const years = expMatch
    ? Number(expMatch[1])
    : 0;

  const minimum =
    Number(candidate.minimumExperience) > 0
      ? Number(candidate.minimumExperience)
      : 3;

  const experience = Math.round(
    25 *
    Math.min(years / minimum, 1) *
    roleFactor *
    (coreCount > 0 ? 1 : 0.5)
  );

  // 5. RELEVANT PROJECTS: 20

  const backendWords = [
    "python", "fastapi", "flask", "django",
    "rest api", "api request", "service endpoints",
    "backend service", "python based",
    "database queries", "data access",
    "database access", "database query",
    "postgresql", "sql"
  ];

  const backendWorkEvidence = jobs
    .split(/\n\s*[•*]\s*/)
    .slice(1)
    .some(t =>
      action.test(normal(t)) &&
      has(t, backendWords)
    );

  const backendProjectEvidence = projects
    .split(/\n\s*[•*]\s*/)
    .slice(1)
    .some(t =>
      action.test(normal(t)) &&
      has(t, backendWords)
    );

  const quantifiedBackend =
    backendWorkEvidence &&
    /\b\d+\s*%/.test(jobs);

  const projectsScore =
    (backendWorkEvidence ? 8 : 0) +
    (backendProjectEvidence ? 7 : 0) +
    (quantifiedBackend ? 5 : 0);

  // 6. TESTING, DEBUGGING, COLLABORATION: 10

  const eText = evidence.join(" ");

  const practiceParts = {
    testing: has(eText, [
      "pytest", "unit testing", "regression checks",
      "test cases", "test matrix",
      "test evidence", "peer testing"
    ]) ? 4 : 0,

    debugging: has(eText, [
      "error handling", "exception reporting",
      "troubleshoot", "triaged defects",
      "reproduced reported defects",
      "resolved edge case",
      "resolved integration failures",
      "production error", "defects"
    ]) ? 3 : 0,

    collaboration: has(eText, [
      "collaborated", "worked with senior",
      "mentored", "pull requests",
      "peer review", "product and qa teams",
      "integration partners"
    ]) ? 2 : 0,

    delivery: has(eText, [
      "deployment pipelines", "release handovers",
      "release checklists", "monitoring checks",
      "environment configuration"
    ]) ? 1 : 0
  };

  const practices = Object.values(practiceParts)
    .reduce((a, b) => a + b, 0);

  // 7. PREFERRED SKILLS: 5

  const pref = [
    ["Docker", ["docker"]],
    ["Cloud Platform", ["aws", "azure", "gcp"]],
    ["CI/CD", [
      "ci cd", "github actions",
      "deployment pipelines"
    ]],
    ["Redis", ["redis"]],
    ["Python Framework", [
      "fastapi", "django", "flask"
    ]]
  ];

  let preferred = 0;

  for (const [skill, terms] of pref) {
    if (claimed(terms) || applied(terms)) {
      preferred++;
      matchedSkills.push(
        `${skill} (preferred)`
      );
    }
  }

  // 8. STRICT FINAL SCORE

  let score =
    required +
    experience +
    projectsScore +
    practices +
    preferred;

  if (coreCount === 0) {
    score = Math.min(score, 39);
  } else if (
    !coreApplied.python ||
    !coreApplied.api
  ) {
    score = Math.min(score, 59);
  }

  if (
    roleFactor < 0.8 ||
    years < minimum ||
    coreCount < 3
  ) {
    score = Math.min(score, 79);
  }

  score = Math.max(
    0,
    Math.min(100, Math.round(score))
  );

  // 9. EXPERIENCE ALIGNMENT
  // EXACTLY MATCH AIRTABLE SINGLE SELECT OPTIONS

  let experienceAlignment;

  if (!expMatch || roleLines.length === 0) {
    experienceAlignment = "Unknown";
  } else if (
    roleFactor >= 0.8 &&
    years >= minimum &&
    coreCount >= 2
  ) {
    experienceAlignment = "Strong";
  } else if (
    roleFactor >= 0.4 &&
    coreCount >= 1
  ) {
    experienceAlignment = "Moderate";
  } else {
    experienceAlignment = "Weak";
  }

  // 10. OVERALL RECOMMENDATION


let recommendation;

if (
  score >= 80 &&
  roleFactor >= 0.8 &&
  years >= minimum &&
  coreCount === 3
) {
  recommendation = "SHORTLIST";

} else if (score >= 50) {
  recommendation = "SCREENING";

} else if (score >= 35) {
  recommendation = "HOLD";

} else {
  recommendation = "REJECT";
}

  // 11. DETAILED EVALUATION EXPLANATION

  const evaluation = [
    "SIMULATION ONLY: Rule-based CV assessment.",
    `Required technical skills: ${required}/40.`,
    `Relevant experience: ${experience}/25.`,
    `Projects and responsibilities: ${projectsScore}/20.`,
    `Testing, debugging and collaboration: ${practices}/10.`,
    `Preferred skills: ${preferred}/5.`,
    `Experience reported: ${expMatch ? years + " years" : "not verified"}.`,
    `Minimum required experience: ${minimum} years.`,
    `Professional roles: ${roleLines.join("; ") || "not established"}.`,
    `Experience alignment: ${experienceAlignment}.`,
    `Backend relevance factor: ${roleFactor}.`,
    `Demonstrated Python evidence: ${coreApplied.python}.`,
    `Demonstrated API evidence: ${coreApplied.api}.`,
    `Demonstrated database evidence: ${coreApplied.database}.`,
    "Missing evidence means unverified, not necessarily incapable.",
    "Assessment is advisory and requires human review."
  ].join(" ");

  // 12. GEMINI-COMPATIBLE STRUCTURED OUTPUT

  return {
    json: {
      ...candidate,

      testMode: true,
      assessmentSource: "MOCK_RULE_BASED_JS",

      output: {
        candidateId,
        matchScore: score,
        matchedSkills,
        missingSkills,
        experienceAlignment,
        evaluation,
        recommendation
      },

      debugScore: {
        required,
        experience,
        projects: projectsScore,
        practices,
        preferred,
        roleFactor,
        years,
        experienceAlignment,
        coreApplied,
        evidenceLevels
      }
    }
  };
}

return evaluate($json);

/*
 GROUP 8 - EVALUATION CONTRACT VALIDATOR
 Compatible with:
 1. MOCK JavaScript Candidate Evaluator
 2. Gemini Basic LLM Chain + Structured Output Parser

 Mode: Run Once for Each Item
*/

const incoming = $json;

// STEP 1: EXTRACT THE ASSESSMENT

let assessment = incoming.output ?? incoming;

if (typeof assessment === "string") {
  try {
    assessment = JSON.parse(assessment);
  } catch (error) {
    throw new Error(
      "Evaluation output is not valid JSON: " + error.message
    );
  }
}

if (
  !assessment ||
  typeof assessment !== "object" ||
  Array.isArray(assessment)
) {
  throw new Error(
    "Evaluation must be a JSON object"
  );
}

// STEP 2: VALIDATE CANDIDATE ID

const candidateId = String(
  assessment.candidateId ?? ""
).trim();

if (!candidateId) {
  throw new Error(
    "Evaluation missing candidateId"
  );
}

// STEP 3: RECOVER TRUSTED CANDIDATE CONTEXT
// Never trust an AI-generated Airtable Record ID.

let context = null;

// The mock evaluator preserves candidate context.
if (
  incoming.candidateRecordId &&
  incoming.candidateId
) {
  context = incoming;
}

// Gemini may return only { output: {...} }.
// Recover context using n8n item linking.
if (!context) {
  try {
    const linked =
      $("Prepare AI Evaluation Context").item.json;

    if (linked.candidateId === candidateId) {
      context = linked;
    }
  } catch (error) {
    // Try matching the candidate within the
    // corresponding workflow-loop execution.
  }
}

// Fallback: use candidate ID within this loop run.
if (!context) {
  let matches = [];

  try {
    const items =
      $("Prepare AI Evaluation Context")
        .all(0, $runIndex);

    matches = items.filter(
      item => item.json.candidateId === candidateId
    );
  } catch (error) {
    throw new Error(
      "Could not access candidate context: " +
      error.message
    );
  }

  if (matches.length !== 1) {
    throw new Error(
      `Expected exactly one context record for ` +
      `${candidateId}, found ${matches.length}. ` +
      `Check item linking and loop execution.`
    );
  }

  context = matches[0].json;
}

// STEP 4: PREVENT CANDIDATE MIXING

if (context.candidateId !== candidateId) {
  throw new Error(
    `CANDIDATE MISMATCH: ` +
    `Context=${context.candidateId}, ` +
    `Evaluation=${candidateId}`
  );
}

const candidateRecordId = String(
  context.candidateRecordId ??
  context.airtableRecordId ??
  ""
).trim();

if (!/^rec[A-Za-z0-9]+$/.test(candidateRecordId)) {
  throw new Error(
    `Invalid Airtable Record ID for ${candidateId}`
  );
}

if (
  incoming.candidateRecordId &&
  incoming.candidateRecordId !== candidateRecordId
) {
  throw new Error(
    `Airtable record mismatch for ${candidateId}`
  );
}

if (!context.jobId) {
  throw new Error(
    `Missing Job ID for ${candidateId}`
  );
}

// STEP 5: VALIDATE MATCH SCORE

const matchScore = assessment.matchScore;

if (
  typeof matchScore !== "number" ||
  !Number.isInteger(matchScore) ||
  matchScore < 0 ||
  matchScore > 100
) {
  throw new Error(
    `Invalid matchScore for ${candidateId}. ` +
    `Expected integer from 0 to 100.`
  );
}

// STEP 6: VALIDATE SKILLS ARRAYS

function validateSkills(value, field) {
  if (
    !Array.isArray(value) ||
    !value.every(
      item =>
        typeof item === "string" &&
        item.trim().length > 0
    )
  ) {
    throw new Error(
      `Invalid ${field} for ${candidateId}`
    );
  }

  return [...new Set(
    value.map(item => item.trim())
  )];
}

const matchedSkills = validateSkills(
  assessment.matchedSkills,
  "matchedSkills"
);

const missingSkills = validateSkills(
  assessment.missingSkills,
  "missingSkills"
);

// STEP 7: VALIDATE TEXT FIELDS

function requiredText(value, field) {
  if (
    typeof value !== "string" ||
    value.trim().length < 10
  ) {
    throw new Error(
      `Missing or insufficient ${field} for ${candidateId}`
    );
  }

  return value.trim();
}


const allowedAlignments = [
  "Strong",
  "Moderate",
  "Weak",
  "Unknown"
];

const experienceAlignment =
  assessment.experienceAlignment;

if (!allowedAlignments.includes(experienceAlignment)) {
  throw new Error(
    `Invalid experienceAlignment for ${candidateId}: ` +
    String(experienceAlignment)
  );
}


const evaluation = requiredText(
  assessment.evaluation,
  "evaluation"
);

// STEP 8: VALIDATE RECOMMENDATION

const recommendation = assessment.recommendation;
const allowedRecommendations = [
  "SHORTLIST",
  "SCREENING",
  "HOLD",
  "REJECT"
];

if (!allowedRecommendations.includes(recommendation)) {
  throw new Error(
    `Invalid recommendation for ${candidateId}: ` +
    String(recommendation)
  );
}

// STEP 9: IDENTIFY THE ASSESSMENT SOURCE

const sourceLabel = String(
  incoming.assessmentSource ?? ""
);

const isMockEvaluation =
  incoming.testMode === true ||
  sourceLabel.startsWith("MOCK_");

const evaluationSource = isMockEvaluation
  ? sourceLabel || "MOCK_EVALUATOR"
  : "GEMINI_AI";

// STEP 10: RETURN ONE STANDARDIZED RECORD

return {
  json: {
    candidateId,
    candidateRecordId,
    airtableRecordId: candidateRecordId,

    candidateName:
      context.candidateName ??
      context.fullName ??
      "",

    jobId: context.jobId,

    matchScore,
    matchedSkills,
    missingSkills,
    experienceAlignment,
    evaluation,
    recommendation,

    evaluationSource,
    isMockEvaluation,
    testMode: isMockEvaluation,
    validationStatus: "VALID",

    evaluatedAt: new Date().toISOString(),

    executionId: String($execution.id ?? "")
  }
};

/*
 GROUP 8 - BUSINESS RULES
 Compatible with Gemini and JavaScript evaluations.
 Mode: Run Once for Each Item
*/

// Get the verified evaluation, not the Airtable output.
const e = $("Validate and Normalize Evaluation").item.json;

// Confirm Airtable updated the correct candidate.
if ($json.id && $json.id !== e.candidateRecordId) {
  throw new Error("Airtable candidate record mismatch");
}

if (e.validationStatus !== "VALID") {
  throw new Error("Candidate evaluation is not validated");
}

const score = e.matchScore;
const recommendation = e.recommendation;

if (!Number.isInteger(score) || score < 0 || score > 100) {
  throw new Error("Invalid match score");
}

// Determine the expected recommendation by score.
const expected =
  score >= 80 ? "SHORTLIST" :
  score >= 50 ? "SCREENING" :
  score >= 35 ? "HOLD" :
  "REJECT";

const mismatch = recommendation !== expected;

let routingDecision;
let requestedState;
let nextAction;
let requiresHumanReview = false;

// Route 1: Inconsistent evaluation.
if (mismatch) {
  routingDecision = "HOLD";
  requestedState = "HOLD";
  nextAction = "Review conflicting evaluation";
  requiresHumanReview = true;

// Route 2: Qualified for technical screening.
} else if (
  recommendation === "SHORTLIST" ||
  recommendation === "SCREENING"
) {
  routingDecision = "SCREENING";
  requestedState = "SCREENING";
  nextAction = "Generate technical screening questions";

// Route 3: Requires clarification.
} else if (recommendation === "HOLD") {
  routingDecision = "HOLD";
  requestedState = "HOLD";
  nextAction = "Recruiter to review candidate";
  requiresHumanReview = true;

// Route 4: Rejection requires human review.
} else {
  routingDecision = "REJECT";
  requestedState = "HOLD";
  nextAction = "Recruiter to review rejection";
  requiresHumanReview = true;
}

const reason = mismatch
  ? `Score ${score} suggests ${expected}, but evaluation returned ${recommendation}.`
  : `Score ${score}/100. Recommendation: ${recommendation}. Route: ${routingDecision}.`;

return {
  json: {
    candidateId: e.candidateId,
    candidateRecordId: e.candidateRecordId,
    jobId: e.jobId,

    matchScore: score,
    recommendation,
    experienceAlignment: e.experienceAlignment,

    routingDecision,
    requestedState,
    nextAction,
    reason,
    requiresHumanReview,

